import{_ as a,o as t,c as n,j as r}from"./chunks/framework.DsyGq6Zh.js";const h=JSON.parse('{"title":"Literature Review and NJIT Faculty Connections","description":"Selective research foundations for provenance-governed knowledge artifacts, adaptive sensors, and human-attention-aware orchestration.","frontmatter":{"title":"Literature Review and NJIT Faculty Connections","description":"Selective research foundations for provenance-governed knowledge artifacts, adaptive sensors, and human-attention-aware orchestration."},"headers":[],"relativePath":"research/systems/literature-and-faculty.md","filePath":"research/systems/literature-and-faculty.md"}'),i={name:"research/systems/literature-and-faculty.md"};function o(s,e,l,d,c,u){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="literature-review-and-njit-faculty-connections" tabindex="-1">Literature Review and NJIT Faculty Connections <a class="header-anchor" href="#literature-review-and-njit-faculty-connections" aria-label="Permalink to &quot;Literature Review and NJIT Faculty Connections&quot;">​</a></h1><p><em>Research reading map · November 19, 2026 · Preliminary, not systematic</em></p><p>This bibliography links the developing research proposal to work on software engineering, sensing, decision models, HCI, business innovation, knowledge graphs, and human–AI evaluation. It does <strong>not</strong> imply these faculty members have agreed to supervise or endorse the proposed research. Research alignments are my interpretations, not claims about their preferences.</p><h2 id="the-academic-problem" tabindex="-1">The academic problem <a class="header-anchor" href="#the-academic-problem" aria-label="Permalink to &quot;The academic problem&quot;">​</a></h2><p>The thesis is not that provenance, graph retrieval, selective review, or AI quality assessment were individually invented here. The proposed contribution is to evaluate an integrated <strong>progressively commissioned, risk-sensitive knowledge production system</strong> in which sensors expose observations and achieved guarantees, policies govern knowledge promotion, and a capacity-aware scheduler allocates human and machine review.</p><h2 id="njit-faculty-connections" tabindex="-1">NJIT faculty connections <a class="header-anchor" href="#njit-faculty-connections" aria-label="Permalink to &quot;NJIT faculty connections&quot;">​</a></h2><h3 id="jamie-payton-—-adaptive-sensing-query-fidelity-evidence-based-computing-education" tabindex="-1">Jamie Payton — adaptive sensing, query fidelity, evidence-based computing education <a class="header-anchor" href="#jamie-payton-—-adaptive-sensing-query-fidelity-evidence-based-computing-education" aria-label="Permalink to &quot;Jamie Payton — adaptive sensing, query fidelity, evidence-based computing education&quot;">​</a></h3><p><strong>Dean, Ying Wu College of Computing</strong> (appointed July 2024). Relevant research areas include mobile/pervasive systems, adaptive data acquisition, formal query fidelity, and computing education.</p><ul><li>Payton, Julien, Roman, and Rajamani, <strong><a href="https://doi.org/10.1145/1734229.1734231" target="_blank" rel="noreferrer">Semantic Self-Assessment of Query Results in Dynamic Environments</a></strong> (ACM TOSEM, 2010). The system assesses achievable query consistency under changing conditions and reports attained guarantees. <em>Narrower connection:</em> a system can report the <strong>query consistency guarantee actually achieved</strong>, rather than promising a guarantee it could not attain. This is about distributed-network query semantics, not the truth of an AI-extracted claim or authorization to promote it.</li><li>Payton, Souvenir, and Liu, <strong><a href="https://researchwith.njit.edu/en/publications/an-architecture-to-support-learning-based-adaptation-of-persisten/" target="_blank" rel="noreferrer">An Architecture to Support Learning-Based Adaptation of Persistent Queries in Mobile Environments</a></strong> (2009). <em>Narrower connection:</em> learning-based choice among query strategies as conditions change. This is not evidence of human-supervised AI policy commissioning.</li><li>Payton et al., <strong><a href="https://computing.njit.edu/computing-education-research-0" target="_blank" rel="noreferrer">BRIDGES: real-world data and visualization in data structures assignments</a></strong> (institutional research summary; original work 2016). The institutional page also describes current inquiry into AI-generated personalized challenge problems based on demonstrated proficiency. <em>Connection:</em> personalized knowledge artifacts and assessment-guided education.</li><li>Payton, <strong><a href="https://cis.temple.edu/~payton/index.php?id=publications" target="_blank" rel="noreferrer">Publications and research</a></strong> and <strong><a href="https://computing.njit.edu/dean" target="_blank" rel="noreferrer">NJIT Dean&#39;s Message</a></strong>.</li></ul><p><strong>Relevance boundary:</strong> these are supporting precedents for adaptive acquisition and explicit achieved guarantees, not direct foundations for graph provenance, consequence-aware human deferral, or decision authority. Payton&#39;s stated contemporary research also emphasizes pervasive computing, smart health/well-being, inclusive computing, and evidence-based education. These publications may inform a sensor-result contract, but should not be presented as direct validation of the proposed human–AI governance system.</p><h3 id="fadi-p-deek-—-process-cognition-tools-and-evidence-based-evaluation" tabindex="-1">Fadi P. Deek — process, cognition, tools and evidence-based evaluation <a class="header-anchor" href="#fadi-p-deek-—-process-cognition-tools-and-evidence-based-evaluation" aria-label="Permalink to &quot;Fadi P. Deek — process, cognition, tools and evidence-based evaluation&quot;">​</a></h3><ul><li>Deek, Turoff, and McHugh, <strong><a href="https://digitalcommons.njit.edu/fac_pubs/16112/" target="_blank" rel="noreferrer">A Common Model for Problem Solving and Program Development</a></strong> (IEEE Transactions on Education, 1999): formalize, plan, design, translate, test, deliver. <em>Connection:</em> natural-language-directed development must still preserve process and verifiable stages.</li><li>Deek et al., <strong><a href="https://digitalcommons.njit.edu/fac_pubs/16646/" target="_blank" rel="noreferrer">On the Evaluation of a Problem Solving and Program Development Environment</a></strong> (1997), describing SOLVEIT and an evaluated integrated workbench. <em>Connection:</em> test engineering methods by building software instruments, not only proposing them.</li><li>DeFranco-Tommarello and Deek, <strong><a href="https://digitalcommons.njit.edu/fac_pubs/19489/" target="_blank" rel="noreferrer">A Study of Collaborative Software Development Using Groupware Tools</a></strong> (2005). The study compares technology and collaborative process combinations. <em>Connection:</em> separate the effects of methods, tools, and interaction in experiments.</li><li>Burns, Klashner, and Deek, <strong><a href="https://digitalcommons.njit.edu/fac_pubs/12709/" target="_blank" rel="noreferrer">An Empirical Evaluation of a Methodology-Tailoring Information System Development Model</a></strong> (2008). <em>Connection:</em> not every traditional Agile process fits every agentic task. Method tailoring should be experimentally evaluated.</li></ul><h3 id="cheickna-sylla-—-multi-criteria-decision-support-and-constrained-optimization" tabindex="-1">Cheickna Sylla — multi-criteria decision support and constrained optimization <a class="header-anchor" href="#cheickna-sylla-—-multi-criteria-decision-support-and-constrained-optimization" aria-label="Permalink to &quot;Cheickna Sylla — multi-criteria decision support and constrained optimization&quot;">​</a></h3><ul><li>Sylla and Wen, <strong><a href="https://digitalcommons.njit.edu/fac_pubs/14771/" target="_blank" rel="noreferrer">A Conceptual Framework for Evaluation of Information Technology Investments</a></strong> (International Journal of Technology Management, 2002). Their GAHP proposal combines goal programming and analytic hierarchy methods, taking tangible/intangible benefits and risk into account. <em>Connection:</em> review routing must optimize more than one objective (quality, expected loss, reviewer capacity, inference cost, rights and privacy). Review capacity and authority are hard constraints, not mere weights.</li></ul><p>This is a foundation for defining the decision model, not a claim that our routing mechanism is already validated.</p><h3 id="michael-a-ehrlich-—-economic-risk-innovation-and-commercialization" tabindex="-1">Michael A. Ehrlich — economic risk, innovation and commercialization <a class="header-anchor" href="#michael-a-ehrlich-—-economic-risk-innovation-and-commercialization" aria-label="Permalink to &quot;Michael A. Ehrlich — economic risk, innovation and commercialization&quot;">​</a></h3><ul><li>Parhankangas and Ehrlich, <strong><a href="https://doi.org/10.1016/j.jbusvent.2013.08.001" target="_blank" rel="noreferrer">How Entrepreneurs Seduce Business Angels: An Impression Management Approach</a></strong> (Journal of Business Venturing, 2014). <em>Connection:</em> claims of value should be substantiated, and founder narratives should not substitute for experimental evidence.</li><li>Ehrlich&#39;s finance, entrepreneurship and innovation work offers an economic framing: how many qualified artifacts can be produced for a given combination of specialist attention, compute expense, and expected error consequences?</li></ul><p>The study should include a real user-value and deployment-cost model, not rely on speculative market-size arguments.</p><h3 id="quentin-jones-—-interruption-management-context-hci-and-progressive-disclosure" tabindex="-1">Quentin Jones — interruption management, context, HCI and progressive disclosure <a class="header-anchor" href="#quentin-jones-—-interruption-management-context-hci-and-progressive-disclosure" aria-label="Permalink to &quot;Quentin Jones — interruption management, context, HCI and progressive disclosure&quot;">​</a></h3><ul><li>Grandhi and Jones, <strong><a href="https://digitalcommons.njit.edu/fac_pubs/6913/" target="_blank" rel="noreferrer">Knock, Knock! Who&#39;s There? Putting the User in Control of Managing Interruptions</a></strong> (International Journal of Human-Computer Studies, 2015). The research finds that additional contextual information helps people judge interruption value. <em>Connection:</em> Pit Stops need concise decision context, not full sensor logs.</li><li>Research on interruptibility provides a basis for studying review burden, notification timing, and progressively disclosed evidence. A reviewer might perform better with a short decision recommendation plus optional details than with raw model confidence scores alone.</li></ul><h2 id="broader-foundational-work" tabindex="-1">Broader foundational work <a class="header-anchor" href="#broader-foundational-work" aria-label="Permalink to &quot;Broader foundational work&quot;">​</a></h2><ul><li><strong><a href="https://www.w3.org/TR/prov-o/" target="_blank" rel="noreferrer">W3C PROV-O</a></strong> (2013): entities, activities, agents and derivations. Use as a conceptual backbone for evidence and decisions.</li><li>Edge et al., <strong><a href="https://arxiv.org/abs/2404.16130" target="_blank" rel="noreferrer">From Local to Global: A Graph RAG Approach to Query-Focused Summarization</a></strong> (2024): large-corpus graph summaries; a major baseline for graph-guided retrieval.</li><li>Hevner et al., <strong><a href="https://aisel.aisnet.org/misq/vol28/iss1/6/" target="_blank" rel="noreferrer">Design Science in Information Systems Research</a></strong> (MIS Quarterly, 2004): evaluated design artifacts as a research method.</li><li>Mozannar and Sontag, <strong><a href="https://proceedings.mlr.press/v119/mozannar20b.html" target="_blank" rel="noreferrer">Consistent Estimators for Learning to Defer to an Expert</a></strong> (ICML, 2020): expert-deferral learning; a baseline for routing, not a claim of novelty.</li><li>Yi, Minot, and Lee, <strong><a href="https://aclanthology.org/2026.akbc-1.16/" target="_blank" rel="noreferrer">GRACE: Graph-Grounded Reflective Agent Copilot Engine for Expert-in-the-Loop Knowledge Expansion</a></strong> (2026): return-on-attention and verified knowledge expansion; an especially important contemporary comparator.</li><li>Liu et al., <strong><a href="https://aclanthology.org/2023.emnlp-main.153/" target="_blank" rel="noreferrer">G-Eval: NLG Evaluation using GPT-4 with Better Human Alignment</a></strong> (2023): model-based qualitative evaluation.</li><li>Zheng et al., <strong><a href="https://arxiv.org/abs/2306.05685" target="_blank" rel="noreferrer">Judging LLM-as-a-Judge with MT-Bench and Chatbot Arena</a></strong> (2023): useful and fallible model-based evaluation.</li><li>David J. Anderson, <em>Kanban</em> (2010), and queueing/constraint theory: conceptual foundations for constrained work flow, throughput, and review queues.</li></ul><h2 id="recent-epistemic-and-interface-research-important-prior-art" tabindex="-1">Recent epistemic and interface research (important prior art) <a class="header-anchor" href="#recent-epistemic-and-interface-research-important-prior-art" aria-label="Permalink to &quot;Recent epistemic and interface research (important prior art)&quot;">​</a></h2><p>A substantial 2026 body of work already examines <strong>claims as attributed propositions rather than uniform facts</strong>. It changes what this dissertation should claim as novel.</p><ul><li>Vitali and Pasqual, <a href="https://arxiv.org/abs/2606.15246" target="_blank" rel="noreferrer"><em>Provenance-Enhanced Statements in Knowledge Graphs</em></a> (June 2026 <strong>preprint</strong>): attributed propositions, competing epistemic stances and explicit limits on what can be treated as factual. This is especially close to our proposed difference between reported testimony and established observation.</li><li>Kakatkar and Khatib, <a href="https://papers.ssrn.com/sol3/papers.cfm?abstract_id=7525242" target="_blank" rel="noreferrer"><em>Epistemic Knowledge Graphs: An Approach for Grounding and Explaining AI Claims</em></a> (2026 <strong>working paper</strong>, not established here as peer reviewed): epistemic status, temporal validity, provenance, and explanation trees. Treat its conceptual overlap seriously before asserting novelty.</li><li><a href="https://link.springer.com/article/10.1007/s00521-026-12495-0" target="_blank" rel="noreferrer"><em>Ontology-guided neuro-symbolic GraphRAG for grounded query answering</em></a> (2026): a cybersecurity evaluation of grounded graph materialization, source-traceable edges and citation precision. It provides concrete baselines for the planned knowledge layer.</li><li><a href="https://doi.org/10.1145/3795134" target="_blank" rel="noreferrer"><em>Entity Linking with Wikidata: A Systematic Literature Review</em></a> (2026): an established research basis for entity matching and disambiguation, including challenges around temporal and qualified relations.</li><li><a href="https://www.wikidata.org/wiki/Wikidata:Data_model" target="_blank" rel="noreferrer">Wikidata&#39;s data model</a>: identifiers, typed properties, statement qualifiers and references. External identifiers should enrich local entities; Wikipedia links should remain <strong>navigation/context evidence</strong>, not independently verified semantic relationships.</li><li><a href="https://www.intelligence.gov/mission/our-values/objectivity" target="_blank" rel="noreferrer">Intelligence Community Directive 203</a>: source-quality assessment, uncertainty, alternative interpretations, change explanations and effective visual communication. The proposed briefing should be evaluated against explicit analytic tradecraft rather than military styling.</li></ul><p>This literature suggests narrowing the claimed research contribution toward <strong>progressive policy commissioning, consequence-sensitive review, sensor evidence contracts and allocation of scarce operator attention</strong>. Even this combination requires a systematic prior-art search and comparative experiments.</p><h2 id="preliminary-novelty-matrix" tabindex="-1">Preliminary novelty matrix <a class="header-anchor" href="#preliminary-novelty-matrix" aria-label="Permalink to &quot;Preliminary novelty matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>State of prior art</th><th>Research question left open</th></tr></thead><tbody><tr><td>Hybrid graph/vector RAG</td><td>Established</td><td>Do provenance and contradiction-preserving summaries reduce context without losing evidence?</td></tr><tr><td>Human-in-the-loop graph validation</td><td>Established, including GRACE</td><td>Can case decisions be transformed into scoped, evaluated automation policies that generalize safely?</td></tr><tr><td>Adaptive sensors/query fidelity</td><td>Established in pervasive computing</td><td>Can heterogeneous sensors express limitations and achieved guarantees in a shared contract that supports adaptive review?</td></tr><tr><td>Qualitative model QA plus deterministic checks</td><td>Established techniques</td><td>Does targeted evidence selection and bounded repair reduce review costs without raising escape rates?</td></tr><tr><td>Kanban/WIP/backpressure</td><td>Established</td><td>Does reviewer-capacity-aware routing improve total verified value under cost-of-error constraints?</td></tr><tr><td>Personalized artifacts</td><td>Active research and industry work</td><td>Can one qualified knowledge base produce varied outputs with verifiable citations and lower marginal review cost?</td></tr></tbody></table><h2 id="required-next-phase" tabindex="-1">Required next phase <a class="header-anchor" href="#required-next-phase" aria-label="Permalink to &quot;Required next phase&quot;">​</a></h2><p>This reading map is <strong>selective</strong>. A formal literature review should specify search databases (ACM, IEEE Xplore, Scopus, Web of Science), query strings, inclusion/exclusion dates, screening, a concept-by-study matrix, bibliography exports, and reproducible quality appraisal. It should especially look for 2024–2026 work on active expert deferral, agent policy learning, provenance-aware graphs, and cost-aware generation before claiming research novelty.</p><p><a href="./">Research hub</a> · <a href="./dissertation-proposal">Preliminary proposal</a></p>',31)])])}const m=a(i,[["render",o]]);export{h as __pageData,m as default};
